$root=new PDO("mysql:host={$host};port={$port};charset=utf8mb4",$user,$password,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
$database='gda_attach_test_'.bin2hex(random_bytes(6));if(!preg_match('/^gda_attach_test_[a-f0-9]{12}$/',$database))throw new RuntimeException('Nome descartável inválido.');
function mariaOk(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);}
try{
 $root->exec("CREATE DATABASE `{$database}` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$db=new PDO("mysql:host={$host};port={$port};dbname={$database};charset=utf8mb4",$user,$password,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$db->exec((string)file_get_contents(dirname(__DIR__).'/database/schema.sql'));
 mariaOk((int)$db->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='project_connections'")->fetchColumn()===1,'Instalação limpa não criou project_connections.');ProjectConnectionMigrationService::run($db);ProjectConnectionMigrationService::run($db);ModuleAttachmentProtocolMigrationService::run($db);ModuleAttachmentProtocolMigrationService::run($db);mariaOk((int)$db->query("SELECT COUNT(*) FROM migrations WHERE migration_id IN ('20260806_create_project_connections','20260807_extend_project_connections_protocol')")->fetchColumn()===2,'Migrações não são idempotentes.');mariaOk((int)$db->query("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='project_connections' AND column_name IN ('module_code','module_slug','module_type','module_status','api_version','health_json','compatibility_json','minimum_version','last_communication_at','last_module_update_at')")->fetchColumn()===10,'Colunas do protocolo oficial ausentes.');
 $db->exec("INSERT INTO users(name,email,password_hash,role,status) VALUES('Admin','admin@test.local','x','super_admin','active');INSERT INTO clients(identifier,name,administrator_name,email,status) VALUES('cliente','Cliente','Admin','cliente@test.local','active');INSERT INTO projects(id,name,full_name,code,description,icon,version,url,admin_url,category,status,display_order) VALUES(7,'Caixas','GDA Caixas','gda-caixas','Antigo','wallet','0.9.0',NULL,NULL,NULL,'deploying',1);INSERT INTO client_projects(client_id,project_id,status,activated_at) VALUES(1,7,'active',NOW())");
