 $fk=false;try{$db->exec("INSERT INTO project_connections(project_id,module_instance_id,protocol_version,endpoint_url,connection_status,capabilities_json,attached_at) VALUES(999999,'orphan-instance',1,'https://x.gda.app.br','attached','{}',NOW())");}catch(PDOException){$fk=true;}mariaOk($fk,'Chave estrangeira não protegeu conexão órfã.');echo 'MariaDB aprovado: instalação limpa, migração idempotente, FK, unicidade, conexão, preservação e rollback.'.PHP_EOL;
